func jwt(exp time.Time, n int) string {
	enc := base64.RawURLEncoding.EncodeToString
	payload, _ := json.Marshal(map[string]any{"exp": exp.Unix(), "n": n})
	return enc([]byte(`{"alg":"none"}`)) + "." + enc(payload) + ".sig"
}

